import re


def is_full_distname(string):
    return bool(string.startswith("MRBTS-") and "/" in string)


def remove_mrbts_and_nrbts_part(full_distname):
    """Removes MRBTSID and NRBTSID if present
    resuls:
        "MRBTS-10191/NRBTS-1/NRCELLGRP-0" -> "NRCELLGRP-0"
        "MRBTS-10191/MNL-1"               -> "MNL-1"
        "MRBTS-10191"                     -> ""
    """
    return re.sub("[M, N]RBTS-[0-9]+/*", "", full_distname)


def get_mrbts_id(full_distname):
    return int(full_distname.split("/")[0].split("-")[1])


def get_nrbts_id(full_distname):
    return int(re.search("NRBTS-[0-9]+", full_distname).group(0).split("-")[-1])


def change_mrbtsid(full_distname, new_nrbts_id):
    return re.sub("MRBTS-[0-9]+", "MRBTS-{}".format(new_nrbts_id), full_distname)


def change_nrbtsid(full_distname, new_nrbts_id):
    return re.sub("NRBTS-[0-9]+", "NRBTS-{}".format(new_nrbts_id), full_distname)


def change_mrbts_id_and_nrbts_id(distname, mrbtsid, nrbtsid):
    return change_mrbtsid(change_nrbtsid(distname, nrbtsid), mrbtsid)

